const Engine = Packages.com.twinsoft.convertigo.engine.Engine;

const JSON_RPC_VERSION = "2.0";
const SUPPORTED_PROTOCOL = "2025-06-18";

var headerVersion = SUPPORTED_PROTOCOL;
if (context.httpServletRequest != null) {
  var header = context.httpServletRequest.getHeader("MCP-Protocol-Version");
  if (header != null) {
    headerVersion = String(header);
  }
}

var requestIdJson = null;
var requestIdValue = null;
var requestIdType = "";
var paramsObject = {};
var parseError = null;
var methodName = null;
var callSequence = "";
var callVariables = {};
var responseStatus = "200";
var responseHasBody = true;

if (("" + request).trim().length === 0) {
  parseError = { status: "400", code: -32700, message: "Empty request body" };
} else {
  try {
    var parsed = JSON.parse(request);
    if (!parsed || typeof parsed !== "object" || Array.isArray(parsed)) {
      parseError = { status: "400", code: -32600, message: "Invalid request payload" };
    } else {
      if (parsed.hasOwnProperty("id")) {
        requestIdValue = parsed.id;
        var idType = requestIdValue === null ? "null" : typeof requestIdValue;
        if (idType === "object") {
          idType = "null";
        }
        if (idType !== "string" && idType !== "number" && idType !== "null") {
          parseError = { status: "400", code: -32600, message: "Invalid id type" };
        } else {
          requestIdType = idType;
          try {
            requestIdJson = JSON.stringify(parsed.id);
          } catch (eId) {
            requestIdJson = null;
          }
        }
      } else {
        requestIdJson = null;
        requestIdValue = null;
        requestIdType = "";
      }
      if (!parseError) {
        if (parsed.jsonrpc !== undefined && parsed.jsonrpc !== JSON_RPC_VERSION) {
          parseError = { status: "400", code: -32600, message: "Unsupported JSON-RPC version", data: { expected: JSON_RPC_VERSION, received: parsed.jsonrpc }};
        } else if (typeof parsed.method !== "string" || parsed.method.length === 0) {
          parseError = { status: "400", code: -32600, message: "Missing method name" };
        } else if (headerVersion && headerVersion.length > 0 && headerVersion !== SUPPORTED_PROTOCOL) {
          parseError = { status: "400", code: -32600, message: "Unsupported MCP protocol version", data: { supported: SUPPORTED_PROTOCOL, received: headerVersion }};
        } else {
          methodName = parsed.method;
          if (parsed.params !== undefined && parsed.params !== null) {
            paramsObject = parsed.params;
          }
        }
      }
    }
  } catch (e) {
    parseError = { status: "400", code: -32700, message: "Invalid JSON", data: { message: String(e) } };
  }
}

callSequence = "mcp_error_response";
responseStatus = parseError.status || "400";
callVariables = { status: String(responseStatus), code: String(parseError.code), message: parseError.message, dataJson: parseError.data ? JSON.stringify(parseError.data) : "", requestIdJson: requestIdJson };
